from __future__ import annotations

from dataclasses import dataclass
from time import perf_counter

from virvision.scene import VisualScene
from virvision.vir.query_filter import ConfidenceThresholds

from .description import NaturalDescriptionProjection, TextSurface
from .model import DETAIL_LEVELS, KCS_VERSION, OUTPUT_LANGUAGES, KCSMetrics, KCSRun
from .spatial import GeometricEdgeResolver, SpatialProfile


EDGE_SPATIAL = "edge.spatial"
PROJECTION_NATURAL = "projection.natural"
SURFACE_TEXT = "surface.text"
DEFAULT_STAGES = (EDGE_SPATIAL, PROJECTION_NATURAL, SURFACE_TEXT)


@dataclass(frozen=True)
class KCSProfile:
    language: str = "tr"
    detail: str = "balanced"
    spatial: SpatialProfile = SpatialProfile()

    def __post_init__(self) -> None:
        if self.language not in OUTPUT_LANGUAGES:
            raise ValueError("profile language must be tr or en")
        if self.detail not in DETAIL_LEVELS:
            raise ValueError("profile detail must be compact, balanced or detailed")
        if not isinstance(self.spatial, SpatialProfile):
            raise ValueError("profile spatial must be a SpatialProfile")

    def resolve_request(self, language: str | None, detail: str | None) -> tuple[str, str]:
        language = self.language if language is None else language
        detail = self.detail if detail is None else detail
        if language not in OUTPUT_LANGUAGES:
            raise ValueError("language must be tr or en")
        if detail not in DETAIL_LEVELS:
            raise ValueError("detail must be compact, balanced or detailed")
        return language, detail


@dataclass(frozen=True)
class RouteDefinition:
    stages: tuple[str, ...] = DEFAULT_STAGES

    def __post_init__(self) -> None:
        if not isinstance(self.stages, tuple) or not self.stages:
            raise ValueError("route stages must be a nonempty tuple")
        if any(not isinstance(item, str) or not item for item in self.stages):
            raise ValueError("route stages must be nonempty strings")
        unknown = set(self.stages) - set(DEFAULT_STAGES)
        if unknown:
            raise ValueError(f"unknown route stage: {', '.join(sorted(unknown))}")
        if self.stages != DEFAULT_STAGES:
            raise ValueError("execution stages are missing or out of order")


class Registry:
    def __init__(self) -> None:
        self._bindings: dict[str, object] = {}
        self.resolution_count = 0

    def bind(self, key: str, component: object) -> None:
        if not isinstance(key, str) or not key:
            raise ValueError("registry key must be a nonempty string")
        if key in self._bindings:
            raise ValueError(f"duplicate registry key: {key}")
        self._bindings[key] = component

    def resolve(self, key: str) -> object:
        self.resolution_count += 1
        try:
            return self._bindings[key]
        except KeyError as exc:
            raise ValueError(f"missing registry binding: {key}") from exc


@dataclass(frozen=True)
class ExecutionPlan:
    profile: KCSProfile
    route: RouteDefinition
    edge_resolver: GeometricEdgeResolver
    projection: NaturalDescriptionProjection
    surface: TextSurface

    @property
    def signature(self) -> tuple:
        return (KCS_VERSION, self.route.stages, self.profile)

    def execute(
        self, scene: VisualScene, *, language: str | None = None, detail: str | None = None
    ) -> KCSRun:
        if not isinstance(scene, VisualScene):
            raise ValueError("execution scene must be a VisualScene")
        language, detail = self.profile.resolve_request(language, detail)
        total_started = perf_counter()
        edge_started = perf_counter()
        field = self.edge_resolver.bind(scene)
        edge_ms = (perf_counter() - edge_started) * 1000
        projection_started = perf_counter()
        projection = self.projection.project(field, language, detail)
        projection_ms = (perf_counter() - projection_started) * 1000
        surface_started = perf_counter()
        text = self.surface.emit(projection)
        surface_ms = (perf_counter() - surface_started) * 1000
        total_ms = (perf_counter() - total_started) * 1000
        overhead_ms = max(0.0, total_ms - edge_ms - projection_ms - surface_ms)
        metrics = KCSMetrics(edge_ms, projection_ms, surface_ms, total_ms, overhead_ms)
        return KCSRun(text, field, projection, metrics)


def default_registry(
    profile: KCSProfile, thresholds: ConfidenceThresholds | None = None
) -> Registry:
    registry = Registry()
    registry.bind(EDGE_SPATIAL, GeometricEdgeResolver(profile.spatial, thresholds))
    registry.bind(PROJECTION_NATURAL, NaturalDescriptionProjection(thresholds))
    registry.bind(SURFACE_TEXT, TextSurface())
    return registry


def compile_execution_plan(
    profile: KCSProfile | None = None,
    *,
    thresholds: ConfidenceThresholds | None = None,
    registry: Registry | None = None,
    route: RouteDefinition | None = None,
) -> ExecutionPlan:
    profile = profile or KCSProfile()
    if not isinstance(profile, KCSProfile):
        raise ValueError("profile must be a KCSProfile")
    route = route or RouteDefinition()
    registry = registry or default_registry(profile, thresholds)
    edge = registry.resolve(route.stages[0])
    projection = registry.resolve(route.stages[1])
    surface = registry.resolve(route.stages[2])
    if not isinstance(edge, GeometricEdgeResolver):
        raise ValueError("edge.spatial binding has an invalid component type")
    if not isinstance(projection, NaturalDescriptionProjection):
        raise ValueError("projection.natural binding has an invalid component type")
    if not isinstance(surface, TextSurface):
        raise ValueError("surface.text binding has an invalid component type")
    return ExecutionPlan(profile, route, edge, projection, surface)
